def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opponents += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(budget, 18.0))

    max_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water_days >= 2:
        emergency = max(150.0, max_prev_bid + 8.0)
        return max(0.0, min(budget, emergency))

    if hp <= 4 or no_water_days >= 1:
        if supply <= 17:
            urgent_bid = max(120.0, max_prev_bid + 5.0)
        else:
            urgent_bid = max(92.0, avg_prev_bid + 4.0)
        return max(0.0, min(budget, urgent_bid))

    if supply >= 23:
        base = 24.0
    elif supply >= 20:
        base = 38.0
    elif supply >= 18:
        base = 52.0
    else:
        base = 72.0

    if max_prev_bid <= 20:
        bid = max(base, 22.0)
    elif max_prev_bid <= 80:
        bid = max(base, max_prev_bid + 2.5)
    elif max_prev_bid <= 120:
        bid = max(base, 58.0)
    else:
        bid = max(base, 46.0)

    if urgent_opponents >= 2 and supply <= 18:
        bid += 10.0
    if rich_opponents >= 2 and supply <= 17:
        bid += 8.0
    if day >= 8 and hp >= 7:
        bid -= 6.0

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    cap = budget
    if budget > reserve_floor:
        cap = budget - reserve_floor * 0.15

    bid = min(bid, cap)
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 40.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max(avg_prev * 1.1, 75.0))
    else:
        bid = min(my_status['budget'], max(avg_prev * 0.9, 45.0))

    return float(bid)
